import{loadStreamNight}from'./night/load.mjs';
import{STREAM_SCENE as R}from'./scene.mjs';import{INPUT_PINS}from'./pins.mjs';import{createStreamContinuousCamera}from'./continuous-camera.mjs';import{createSelectedStreamWater}from'./water.mjs';import{loadSelectedPlayerFrames}from'../gohyeon-pair/player_frames/load-player-frames.mjs';import{selectPlayerFrame}from'../gohyeon-pair/player-frame.mjs';
const moduleURL=import.meta.url,KEYS=['sceneId','mapId','revision','imageSHA','maskSHA','foot','facing'];
const hash=async b=>[...new Uint8Array(await crypto.subtle.digest('SHA-256',b))].map(v=>v.toString(16).padStart(2,'0')).join('');
const point=f=>{if(!Array.isArray(f)||Object.getPrototypeOf(f)!==Array.prototype||Reflect.ownKeys(f).length!==3)return null;const d=[0,1].map(i=>Object.getOwnPropertyDescriptor(f,String(i)));return d.every(x=>x?.enumerable&&Object.hasOwn(x,'value')&&Number.isSafeInteger(x.value))?d.map(x=>x.value):null};
// Pure fixed presentation: no world, pose owner, clock owner, RAF, save or gameplay authority.
export async function prepareYeonchoStream({signal,fetcher=fetch,decode=async b=>createImageBitmap(new Blob([b])),imageCrop=async(im,x,y,w,h)=>createImageBitmap(im,x,y,w,h),canvasFactory}={}){
 let disposed=false,actors=null,camera=null,water=null,night=null;const images=new Set(),closed=new WeakSet();
 const close=im=>{if(im&&!closed.has(im)){closed.add(im);try{im.close?.()}catch{}}};
 const check=()=>{if(disposed||signal?.aborted)throw Error('STREAM_PREPARE_CANCELLED')};
 const dispose=()=>{if(disposed)return;disposed=true;for(const cleanup of [()=>camera?.dispose(),()=>water?.dispose(),()=>night?.dispose(),()=>actors?.dispose()])try{cleanup()}catch{}for(const im of images)close(im);images.clear()};
 const read=async path=>{check();const pin=INPUT_PINS[path];if(!pin)throw Error('UNKNOWN_STREAM_RESOURCE');const r=await fetcher(new URL(path,moduleURL),{signal});if(!r.ok)throw Error('STREAM_INPUT_MISSING');const raw=await r.arrayBuffer(),b=new Uint8Array(raw instanceof ArrayBuffer?raw.slice(0):raw);check();if(b.length!==pin.bytes||await hash(b)!==pin.sha256)throw Error('STREAM_PIN_MISMATCH');check();return b};
 const decodeOwned=async b=>{check();const im=await decode(b);if(disposed||signal?.aborted){close(im);throw Error('STREAM_PREPARE_CANCELLED')}images.add(im);return im};
 try{
  const [art,mask,cb,oc,npc]=await Promise.all(['../s1-local/assets/yeoncho-open.png','assets/bounded-safe.u8','assets/camera-bounds.json','assets/opaque-origins.json','../../assets/approved-atlases/npc/LOCAL_RESIDENT_M_BASE.png'].map(read));
  if(mask.length!==1448*5159)throw Error('STREAM_MASK_SHAPE');const bounds=JSON.parse(new TextDecoder().decode(cb)),origins=JSON.parse(new TextDecoder().decode(oc));
  const safe=foot=>{const p=point(foot);return!disposed&&!!p&&p[0]>=984&&p[0]<2432&&p[1]>=1550&&p[1]<6709&&mask[(p[1]-1550)*1448+p[0]-984]===1};
  const opaque=([x,y])=>origins.originRows[y]?.some(([a,b])=>x>=a&&x<b)??false;
  actors=await loadSelectedPlayerFrames({fetcher:async url=>{check();const r=await fetcher(url,{signal});if(!r.ok)return r;const raw=await r.arrayBuffer(),bytes=new Uint8Array(raw instanceof ArrayBuffer?raw.slice(0):raw);check();return{ok:true,arrayBuffer:async()=>bytes}},decode:async b=>{const im=await decodeOwned(b);return Object.freeze({width:im.width,height:im.height,image:im,close:()=>close(im)})}});
  let image=await decodeOwned(art);const resident=await decodeOwned(npc);if(image.width!==4812||image.height!==6709||resident.width!==393||resident.height!==784)throw Error('STREAM_IMAGE_DIMENSIONS');const full=image;image=await imageCrop(full,984,1298,1448,5411);images.add(image);check();if(image.width!==1448||image.height!==5411)throw Error('STREAM_CROP_DIMENSIONS');close(full);images.delete(full);check();
  const trainerRows=[{"path":"../../assets/approved-atlases/npc/LOCAL_WALKER_F_VAR01.png","foot":[1760,3000],"frame":[12,394,127,192],"width":456,"height":784},{"path":"../../assets/approved-atlases/npc/ANGLER_M_BASE.png","foot":[1155,5000],"frame":[3,2,120,192],"width":381,"height":784}],trainerImages=[];for(const r of trainerRows){const im=await decodeOwned(await read(r.path));if(im.width!==r.width||im.height!==r.height)throw Error('STREAM_TRAINER_ATLAS_DIMENSIONS');trainerImages.push(im)}
  const registration=JSON.parse(new TextDecoder().decode(await read('assets/water-registration.json'))),middleRegistration=JSON.parse(new TextDecoder().decode(await read('assets/water/middle_REGISTRATION.json')));
  const [cdSource,cdWater,cg,middleSource,middleWater,mg]=await Promise.all(['cd_source_rgba.bin','cd_water_u8.bin','cd_gain_f64le.bin','middle_source_rgba.bin','middle_water_u8.bin','middle_gain_f64le.bin'].map(n=>read('assets/water/'+n)));
  const lower=[];for(let i=0;i<24;i++){const im=await decodeOwned(await read('assets/water/lower_'+String(i).padStart(2,'0')+'.png'));if(im.width!==330||im.height!==620)throw Error('LOWER_WATER_DIMENSIONS');lower.push(im)}
  water=createSelectedStreamWater({registration,middleRegistration,cdSource,cdWater,cdGain:new Float64Array(cg.buffer),middleSource,middleWater,middleGain:new Float64Array(mg.buffer),lower});check();night=await loadStreamNight({fetcher,signal,image,actors:actors.actors,canvasFactory});check();
  const resetCameraForSceneOrRestore=foot=>{if(!safe(foot))throw Error('UNSUPPORTED_STREAM_POSE');camera?.dispose();camera=createStreamContinuousCamera({initialFoot:foot,isSupportedFoot:safe,isOpaqueOrigin:opaque,bounds});return camera.getOrigin()};
  const validate=n=>{if(disposed)return'STREAM_PRESENTATION_DISPOSED';if(!n||Object.getPrototypeOf(n)!==Object.prototype||Reflect.ownKeys(n).length!==7||KEYS.some(k=>{const d=Object.getOwnPropertyDescriptor(n,k);return!d?.enumerable||!Object.hasOwn(d,'value')}))return'INVALID_STREAM_LOCATION';if(['sceneId','mapId','revision','imageSHA','maskSHA'].some(k=>n[k]!==R[k]))return'STREAM_LOCATION_PIN_MISMATCH';return['up','down','left','right'].includes(n.facing)&&safe(n.foot)?true:'UNSUPPORTED_STREAM_POSE'};
  return Object.freeze({pinsVerified:true,safe,validate,resetCameraForSceneOrRestore,draw(ctx,{foot,facing,elapsedMs=0,moving=false,minutes=720,lights=true,rest=false}){if(!safe(foot)||!['up','down','left','right'].includes(facing))throw Error('UNSUPPORTED_STREAM_POSE');if(ctx.canvas.width!==960||ctx.canvas.height!==540)throw Error('STREAM_PINNED_VIEWPORT');const origin=camera?camera.trackFoot(foot):resetCameraForSceneOrRestore(foot);ctx.save();try{ctx.imageSmoothingEnabled=false;ctx.clearRect(0,0,960,540);ctx.drawImage(image,origin[0]-984,origin[1]-1298,960,540,0,0,960,540);water.draw(ctx,origin,elapsedMs);const frame=selectPlayerFrame({facing,walking:moving,elapsedMs});const drawResident=()=>ctx.drawImage(resident,2,2,127,192,1210-origin[0]-127*80/192/2,2740-origin[1]-80,127*80/192,80),drawPlayer=()=>ctx.drawImage(actors.actors['actor:'+frame].image,foot[0]-origin[0]-53,foot[1]-origin[1]-90);const layers=[{y:2740,draw:drawResident},{y:foot[1],draw:drawPlayer},...trainerRows.map((r,i)=>({y:r.foot[1],draw:()=>{const[sx,sy,sw,sh]=r.frame;ctx.drawImage(trainerImages[i],sx,sy,sw,sh,r.foot[0]-origin[0]-sw*80/sh/2,r.foot[1]-origin[1]-80,sw*80/sh,80)}}))];layers.sort((a,b)=>a.y-b.y);for(const layer of layers)layer.draw();night.depth(ctx,origin,foot);night.apply(ctx,origin,{foot,frame,minutes,lights,rest})}finally{ctx.restore()}},dispose});
 }catch(e){dispose();throw e}
}
